#!/bin/bash
# Test: generated files are in sync with sources.
# Usage: bash tests/test_build.sh  (from repo root)
# It copies current generated files to temp, rebuilds, and fails if
# the rebuild differs (meaning someone edited argosbx.sh/index.html
# by hand without rebuilding, or a module change was not rebuilt).
set -e
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
TMP="$(mktemp -d)"
trap 'rm -rf "$TMP"' EXIT
cp "$ROOT/argosbx.sh" "$TMP/argosbx.sh.before"
cp "$ROOT/index.html" "$TMP/index.html.before"
cp "$ROOT/container/nodejs/start.sh" "$TMP/start.sh.before"
python3 "$ROOT/build/build.py" > "$TMP/build.log" 2>&1 || { cat "$TMP/build.log"; echo "FAIL: build.py failed"; exit 1; }
diff -u "$TMP/argosbx.sh.before" "$ROOT/argosbx.sh" || { echo "FAIL: argosbx.sh out of sync with build (rebuild and commit)"; exit 1; }
diff -u "$TMP/index.html.before" "$ROOT/index.html" || { echo "FAIL: index.html out of sync with build (rebuild and commit)"; exit 1; }
diff -u "$TMP/start.sh.before" "$ROOT/container/nodejs/start.sh" || { echo "FAIL: container start.sh out of sync with build (rebuild and commit)"; exit 1; }
# Generated headers must be present, and the scripts must parse.
head -n 2 "$ROOT/argosbx.sh" | grep -q "GENERATED BY build/build.py" || { echo "FAIL: argosbx.sh missing GENERATED header"; exit 1; }
head -n 2 "$ROOT/index.html" | grep -q "GENERATED BY build/build.py" || { echo "FAIL: index.html missing GENERATED header"; exit 1; }
head -n 2 "$ROOT/container/nodejs/start.sh" | grep -q "GENERATED BY build/build.py" || { echo "FAIL: container start.sh missing GENERATED header"; exit 1; }
bash -n "$ROOT/argosbx.sh" || { echo "FAIL: bash -n argosbx.sh"; exit 1; }
bash -n "$ROOT/container/nodejs/start.sh" || { echo "FAIL: bash -n container start.sh"; exit 1; }
echo "PASS: build sync + syntax"
